beh('B-recovery','A3','Constructor before startup; main loop install handler and FSM restore owner','Snapshot index/term and configuration plus retained log suffix','NewRaft restart or InstallSnapshot request',['s-recovery','s-install','s-repl-snapshot','s-store','s-state'],implementation_guards=['Constructor reads durable term and log end; tries snapshots newest first and scans later logs for configurations. Install rejects older terms or unsupported snapshot versions; verifies stream size and completes restore future before success.'],writes=['Last-applied and last-snapshot coordinates, latest/committed configurations; replication success advances peer nextIndex/match to snapshot index.'],external_effects=['FSM restore discards previous state; old logs compacted, or all removed for monotonic store.'],produces_fact_ids=['F-match'],cross_activity_effects={'A1':'A successful installed snapshot supplies peer match support through its index.','A2':'Recovered history and term constrain the next campaign freshness; incoming newer snapshot term changes authority.','A4':'Snapshot configuration reconstructs participant eligibility.'},unknowns=['Same-term delayed/duplicate snapshot delivery and retained conflicting suffix histories have not been reconstructed.'])
