F=[dict(id='F-match',meaning='For each voter ID tracked by one commitment object, the highest index reported matched by local successful storage, successful append reply, or successful snapshot installation; reports increase monotonically within that tracker.',identity={'owner':'commitment object belonging to one leader lifetime','peer':'ServerID'},validity_context='Eligible only while that object is consumed by its leader lifetime and the ID remains a voter in its current matchIndexes. This accounting assertion does not prove durable storage correctness.',representation=['commitment.matchIndexes[ServerID]'],invalidators=['B-leader-lifetime'],reinterpreters=['B-configuration'],durability='Volatile support accounting; reported log/snapshot data resides in injected stores.',recovery='New leadership creates zero-valued support for configured voters and collects fresh reports.',source_ids=['s-commitment','s-dispatch','s-repl-result','s-repl-snapshot','s-leader-setup']),dict(id='F-commit-frontier',meaning='The commitment object has computed a strict-majority voter match index at or above its first current-term log index, and retains the greatest such index.',identity={'owner':'commitment object / leadership lifetime'},validity_context='Computed over latest configured voters; valid consumption is by the leader main loop owning this object. It is a support-derived index, not FSM completion.',representation=['commitment.commitIndex','commitment.startIndex'],invalidators=['B-leader-lifetime'],reinterpreters=['B-configuration'],durability='Volatile; actual logs and snapshots are durable through their stores.',recovery='Recomputed in each leader lifetime; prior decided history constrains elections via retained log/snapshot and voting freshness.',source_ids=['s-commitment','s-leader-setup','s-leader-loop','s-vote']),dict(id='F-verify-tally',meaning='One verification future records its initial self count plus affirmative notifyAll callbacks received before its notification channel is cleared; quorumSize was computed from the voter count at admission. The tally itself carries no participant identity or suffrage.',identity={'operation':'verifyFuture object','owner':'leader lifetime registering the future'},validity_context='Pending verification registered by verifyLeader; callback count is interpreted by leaderLoop against captured quorumSize. It does not itself assert that every callback came from a voter or that a voter majority confirmed authority.',representation=['verifyFuture.votes','verifyFuture.quorumSize','verifyFuture.notifyCh','followerReplication.notify'],invalidators=['B-leader-lifetime'],reinterpreters=[],durability='Volatile per-request state.',recovery='Pending futures receive leadership-loss error on leader exit; fresh calls allocate new futures.',source_ids=['s-verify-register','s-repl-notify','s-verify-future','s-leader-loop'])]
